# PR Review Implementation Plan

## Architecture Overview

```
User clicks "Review" on file tab
    → POST /api/git/pr/review { from_branch, to_branch, file_path, diff }
    → Backend: AI analyzes diff, returns structured comments
    → Store in chat.metadata.pr_view[file_path].comments
    → Save chat (persistence)
    → PRViewer renders AI comments inline on diff lines
```

## What We'll Build

1. **API endpoint** - `api.repo.reviewFile()` 
2. **PRChangesPanel** - "Review" button on file tabs, calls API, stores in chat metadata
3. **PRViewer** - Merge AI comments with user comments in diff view, show severity badges

---

## Backend API Module

```js src/api/modules/git.js (new)
// New endpoint for AI-powered PR file review
```

First, let's add the endpoint to `api.js`:

```js src/api/api.js
    repo: {
      info() {
        return API.get('/api/git/repo/info')
      },
      branches() {
        return API.get('/api/git/repo/branches')
      },
      commits(branch) {
        return API.get(`/api/git/repo/branch/commits?branch=${encodeURIComponent(branch)}`)
      },
      changes({ from_branch, to_branch }) {
        return API.get(`/api/git/repo/changes?from_branch=${encodeURIComponent(from_branch)}&to_branch=${encodeURIComponent(to_branch)}`)
      },
      readFromBranch(path, branch) {
        return API.get(`/api/git/files/content?path=${encodeURIComponent(path)}&branch=${encodeURIComponent(branch)}`)
      },
      // NEW: AI-powered file diff review
      reviewFile({ from_branch, to_branch, file_path, diff, existing_comments = [] }) {
        return API.post('/api/git/pr/review', {
          from_branch,
          to_branch,
          file_path,
          diff,
          existing_comments
        })
      }
    },
```

---

Now the main components. The key changes are:

1. **PRChangesPanel** - orchestrates review calls, stores results in `chat.metadata.pr_view`
2. **PRViewer** - accepts `aiComments` prop, renders them inline with severity styling

```vue src/components/vibe/panels/PRChangesPanel.vue
<script setup>
import PRViewer from '@/components/repo/PRViewer.vue'
import PRSearchPanel from '@/components/vibe/panels/PRSearchPanel.vue'
import { SplitterGroup, SplitterPanel, SplitterResizeHandle } from 'radix-vue'
</script>

<template>
  <div class="flex flex-col h-full w-full overflow-hidden">
    <!-- Header -->
    <div class="flex items-center gap-2 px-2 py-1.5 bg-base-200/60 shrink-0 border-b border-base-content/10">
      <i class="fa-solid fa-code-pull-request text-info text-sm"></i>
      <span class="text-sm font-bold truncate grow">Pull Request Review</span>

      <!-- Review selected files button -->
      <button
        v-if="selectedFiles.length"
        class="btn btn-xs btn-warning gap-1"
        :class="{ 'loading': reviewingFiles }"
        @click="reviewSelectedFiles"
        :disabled="reviewingFiles"
        title="AI review selected files"
      >
        <i class="fa-solid fa-robot" v-if="!reviewingFiles"></i>
        <span>Review ({{ selectedFiles.length }})</span>
      </button>

      <!-- Search toggle -->
      <button
        class="btn btn-xs"
        :class="showSearch ? 'btn-info' : 'btn-ghost'"
        @click="toggleSearch"
        title="Search in files"
      >
        <i class="fa-solid fa-magnifying-glass"></i>
      </button>

      <button class="btn btn-xs btn-ghost" @click="loadChanges" :disabled="loading" title="Reload">
        <i class="fa-solid fa-rotate-right" :class="{ 'animate-spin': loading }"></i>
      </button>
    </div>

    <!-- Loading state -->
    <div v-if="loading" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/50">
      <i class="fa-solid fa-spinner text-3xl animate-spin"></i>
      <span class="text-sm font-medium">Loading changes...</span>
    </div>

    <template v-else>
      <!-- No active session -->
      <div v-if="!chat" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/40">
        <i class="fa-solid fa-inbox text-4xl"></i>
        <span class="text-sm">No active session</span>
      </div>

      <!-- Main content area -->
      <div v-else class="grow min-h-0 overflow-hidden">
        <!-- Split layout with search -->
        <SplitterGroup v-show="showSearch" direction="horizontal" class="h-full">
          <SplitterPanel :min-size="20" :defaultSize="35" class="overflow-hidden">
            <PRSearchPanel
              ref="searchPanel"
              :files="prFiles"
              :project="project"
              @close="closeSearch"
              @select-file="onSearchSelectFile"
              @jump-to-match="onJumpToMatch"
            />
          </SplitterPanel>

          <SplitterResizeHandle class="w-1 hover:bg-slate-600" />

          <SplitterPanel :min-size="30" :defaultSize="65" class="overflow-hidden">
            <PRViewer
              ref="prViewerSplit"
              :chat="chat"
              :from-branch="currentBranch"
              :to-branch="compareBranch"
              :available-branches="branches"
              :project="project"
              :repo-changes="repoChanges"
              :loading="loading"
              :ai-comments-by-file="aiCommentsByFile"
              :reviewing-file="reviewingFilePathInProgress"
              @refresh="loadChanges"
              @comment="onComment"
              @open-file="onOpenFile"
              @branch-changed="onBranchChanged"
              @compare-branch-changed="onCompareBranchChanged"
              @visible-files-changed="onVisibleFilesChanged"
              @selected-files-changed="onSelectedFilesChanged"
              @review-file="onReviewSingleFile"
              @ai-comment-status-changed="onAiCommentStatusChanged"
            />
          </SplitterPanel>
        </SplitterGroup>

        <!-- PR Viewer only (no search) -->
        <PRViewer
          v-show="!showSearch"
          ref="prViewerFull"
          :chat="chat"
          :from-branch="currentBranch"
          :to-branch="compareBranch"
          :available-branches="branches"
          :project="project"
          :repo-changes="repoChanges"
          :loading="loading"
          :ai-comments-by-file="aiCommentsByFile"
          :reviewing-file="reviewingFilePathInProgress"
          @refresh="loadChanges"
          @comment="onComment"
          @open-file="onOpenFile"
          @branch-changed="onBranchChanged"
          @compare-branch-changed="onCompareBranchChanged"
          @visible-files-changed="onVisibleFilesChanged"
          @selected-files-changed="onSelectedFilesChanged"
          @review-file="onReviewSingleFile"
          @ai-comment-status-changed="onAiCommentStatusChanged"
        />
      </div>
    </template>
  </div>
</template>

<script>
export default {
  props: {
    chat: { type: Object, default: null }
  },
  emits: ['comment'],
  data() {
    return {
      loading: false,
      project: null,
      branches: [],
      currentBranch: 'main',
      compareBranch: 'local',
      repoChanges: null,
      showSearch: false,
      prFiles: [],
      selectedFiles: [],
      reviewingFiles: false,
      reviewingFilePathInProgress: null,
      // AI comments keyed by file_path, loaded from chat.metadata.pr_view
      aiCommentsByFile: {}
    }
  },
  async created() {
    if (this.chat) {
      await this.initialize()
    }
  },
  watch: {
    chat(newChat) {
      if (newChat?.id) this.initialize()
    }
  },
  computed: {
    activeViewer() {
      return this.showSearch ? this.$refs.prViewerSplit : this.$refs.prViewerFull
    }
  },
  methods: {
    async initialize() {
      this.loading = true
      try {
        const chatProject = this.$chats.chatProject(this.chat)
        this.project = chatProject

        if (this.chat?.pr_view?.from_branch) {
          this.currentBranch = this.chat.pr_view.from_branch
        }
        if (this.chat?.pr_view?.to_branch) {
          this.compareBranch = this.chat.pr_view.to_branch
        }

        // Load persisted AI comments from chat metadata
        this.loadPersistedComments()

        if (this.project?.$api) {
          const { branches } = await this.project.$api.repo.branches()
          this.branches = branches || []
          await this.loadChanges()
        }
      } catch (error) {
        console.error('Error initializing PR view:', error)
      } finally {
        this.loading = false
      }
    },

    /** Load AI comments stored in chat.metadata.pr_view per file */
    loadPersistedComments() {
      const prView = this.chat?.metadata?.pr_view || {}
      const byFile = {}
      Object.entries(prView).forEach(([filePath, data]) => {
        if (data?.ai_comments?.length) {
          byFile[filePath] = data.ai_comments
        }
      })
      this.aiCommentsByFile = byFile
    },

    async loadChanges() {
      if (!this.project?.$api) return
      this.loading = true
      try {
        this.repoChanges = await this.project.$api.repo.changes({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch
        })
      } catch (error) {
        console.error('Error loading changes:', error)
        this.repoChanges = null
      } finally {
        this.loading = false
      }
    },

    /** Review a single file triggered from the file tab button */
    async onReviewSingleFile(file) {
      await this.reviewFile(file)
    },

    /** Review all currently selected files */
    async reviewSelectedFiles() {
      if (!this.selectedFiles.length || this.reviewingFiles) return
      this.reviewingFiles = true
      try {
        for (const file of this.selectedFiles) {
          await this.reviewFile(file)
        }
      } finally {
        this.reviewingFiles = false
      }
    },

    /**
     * Call backend to get AI review for a single file diff.
     * Stores result in chat.metadata.pr_view[file_path].ai_comments
     */
    async reviewFile(file) {
      if (!this.project?.$api || !file?.diff) return
      this.reviewingFilePathInProgress = file.fileFullName
      try {
        const existingComments = this.aiCommentsByFile[file.fileFullName] || []
        const result = await this.project.$api.repo.reviewFile({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch,
          file_path: file.fileFullName,
          diff: file.diff,
          existing_comments: existingComments
        })

        const comments = result?.comments || []
        // Merge with existing user status overrides (fixed/false_positive)
        const merged = this.mergeWithExistingStatus(comments, existingComments)

        // Update local state
        this.aiCommentsByFile = {
          ...this.aiCommentsByFile,
          [file.fileFullName]: merged
        }

        // Persist to chat metadata
        await this.persistFileReview(file.fileFullName, merged, result?.summary, result?.score)
      } catch (error) {
        console.error('Error reviewing file:', error)
        this.$ui?.addNotification?.({ text: `Review failed: ${file.title}`, type: 'error' })
      } finally {
        this.reviewingFilePathInProgress = null
      }
    },

    /** Preserve user-set statuses (fixed/false_positive) when re-reviewing */
    mergeWithExistingStatus(newComments, oldComments) {
      return newComments.map(nc => {
        // Match by line number + title similarity
        const existing = oldComments.find(oc =>
          oc.line === nc.line && oc.title === nc.title
        )
        return {
          ...nc,
          status: existing?.status || 'open'
        }
      })
    },

    /** Save AI review results into chat.metadata.pr_view[filePath] */
    async persistFileReview(filePath, comments, summary, score) {
      if (!this.chat) return
      const metadata = { ...(this.chat.metadata || {}) }
      const prView = { ...(metadata.pr_view || {}) }
      prView[filePath] = {
        ...(prView[filePath] || {}),
        ai_comments: comments,
        summary,
        score,
        reviewed_at: new Date().toISOString()
      }
      metadata.pr_view = prView

      // Patch chat metadata and save
      const updatedChat = { ...this.chat, metadata }
      await this.$storex.chats.saveChatInfo(updatedChat)
    },

    /** Handle comment status changes (fixed / false_positive) from PRViewer */
    async onAiCommentStatusChanged({ filePath, commentId, status }) {
      const comments = this.aiCommentsByFile[filePath]
      if (!comments) return

      const updated = comments.map(c =>
        c.id === commentId ? { ...c, status } : c
      )
      this.aiCommentsByFile = { ...this.aiCommentsByFile, [filePath]: updated }
      await this.persistFileReview(
        filePath,
        updated,
        this.chat?.metadata?.pr_view?.[filePath]?.summary,
        this.chat?.metadata?.pr_view?.[filePath]?.score
      )
    },

    async saveBranchSelection() {
      if (!this.chat) return
      try {
        const updatedChat = {
          ...this.chat,
          pr_view: {
            ...(this.chat.pr_view || {}),
            from_branch: this.currentBranch,
            to_branch: this.compareBranch
          }
        }
        await this.$storex.chats.saveChatInfo(updatedChat)
      } catch (error) {
        console.error('Error saving branch selection:', error)
      }
    },

    onVisibleFilesChanged(visibleFiles) {
      this.prFiles = visibleFiles || []
    },

    onSelectedFilesChanged(selectedFiles) {
      this.selectedFiles = selectedFiles || []
    },

    toggleSearch() {
      this.showSearch = !this.showSearch
      if (this.showSearch) {
        this.$nextTick(() => {
          const viewer = this.$refs.prViewerFull
          if (viewer?.visibleFiles) {
            this.prFiles = viewer.visibleFiles
          }
        })
      }
    },

    closeSearch() {
      this.showSearch = false
    },

    onSearchSelectFile(fileResult) {
      const viewer = this.activeViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (file) viewer.selectFile(file)
    },

    onJumpToMatch({ file: fileResult, match }) {
      const viewer = this.activeViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (!file) return
      viewer.selectFile(file)
      if (match.type === 'hunk') return
      const lineIndex = file.diffLines?.findIndex(l =>
        l.type === match.type &&
        (l.newLineNumber === match.lineNumber || l.oldLineNumber === match.lineNumber)
      )
      if (lineIndex !== undefined && lineIndex > -1) {
        viewer.visibleLineComments?.add(lineIndex)
      }
    },

    async onBranchChanged(branch) {
      this.currentBranch = branch
      await this.saveBranchSelection()
      this.loadChanges()
    },

    async onCompareBranchChanged(branch) {
      this.compareBranch = branch
      await this.saveBranchSelection()
      this.loadChanges()
    },

    onComment({ file, line, comment, lineNumber }) {
      this.$emit('comment', {
        file: file.fileFullName,
        lineNumber,
        comment,
        diff: line?.content
      })
    },

    onOpenFile(filePath) {
      this.$ui.openProjectFile(filePath)
    }
  }
}
</script>
```

Now update `PRViewer.vue` to handle AI comments, the review button on file tabs, and severity display:

```vue src/components/repo/PRViewer.vue
<script setup>
import "@git-diff-view/vue/styles/diff-view.css"
import { DiffParser } from "@git-diff-view/vue"
import CodxMenu from "../CodxMenu.vue"
import { SplitterGroup, SplitterPanel, SplitterResizeHandle } from 'radix-vue'
import ChatEntryVue from '../ChatEntry.vue'
import BranchSelector from '@/components/vibe/panels/BranchSelector.vue'
</script>

<template>
  <div class="azure-pr-view flex flex-col h-full overflow-hidden bg-base-100">
    <!-- Top toolbar -->
    <header class="flex items-center justify-between px-3 py-1.5 bg-base-200 border-b border-base-content/10 shrink-0 gap-2 flex-wrap">
      <div class="flex items-center gap-2 grow min-w-0">
        <i class="fa-solid fa-code-branch text-warning shrink-0"></i>
        <BranchSelector
          v-if="project"
          :project="project"
          :current-branch="fromBranch"
          :compare-branch="toBranch"
          :available-branches="availableBranches"
          :loading="loading"
          @branch-changed="onFromBranchChanged"
          @compare-branch-changed="onToBranchChanged"
        />
        <span v-else class="flex items-center gap-2 font-mono text-sm">
          <span class="font-semibold">{{ fromBranch }}</span>
          <i class="fa-solid fa-arrow-right text-xs text-base-content/40"></i>
          <span class="font-semibold">{{ toBranch }}</span>
        </span>
      </div>

      <div class="flex items-center gap-2 shrink-0">
        <div class="flex items-center gap-2 text-xs text-base-content/60">
          <span class="badge badge-sm badge-ghost">
            <i class="fa-solid fa-file-pen text-warning"></i> {{ changeCount }}
          </span>
          <span class="badge badge-sm badge-success badge-ghost">
            <i class="fa-solid fa-plus"></i> {{ insertions }}
          </span>
          <span class="badge badge-sm badge-error badge-ghost">
            <i class="fa-solid fa-minus"></i> {{ deletions }}
          </span>
        </div>

        <div class="divider divider-horizontal mx-1"></div>

        <div class="dropdown dropdown-bottom dropdown-end">
          <button class="btn btn-xs btn-ghost gap-1">
            <i class="fa-solid fa-code-compare"></i>
            <span class="hidden sm:inline">{{ diffViewMode === 'unified' ? 'Unified' : 'Split' }}</span>
            <i class="fa-solid fa-chevron-down text-[8px]"></i>
          </button>
          <ul class="dropdown-content menu bg-base-100 rounded-box z-50 w-32 p-1 shadow">
            <li><a @click="setDiffViewMode('unified')" :class="{ 'active': diffViewMode === 'unified' }">Unified</a></li>
            <li><a @click="setDiffViewMode('split')" :class="{ 'active': diffViewMode === 'split' }">Split</a></li>
          </ul>
        </div>

        <button
          class="btn btn-xs gap-1"
          :class="showFullFile ? 'btn-info' : 'btn-ghost'"
          @click="toggleFullFile"
        >
          <i :class="showFullFile ? 'fa-solid fa-file' : 'fa-solid fa-file-lines'"></i>
          <span class="hidden sm:inline text-[10px]">{{ showFullFile ? 'Full' : 'Diff' }}</span>
        </button>

        <button class="btn btn-xs btn-ghost" @click="navigateFile(-1)" :disabled="!hasPreviousFile">
          <i class="fa-solid fa-chevron-left"></i>
        </button>
        <button class="btn btn-xs btn-ghost" @click="navigateFile(1)" :disabled="!hasNextFile">
          <i class="fa-solid fa-chevron-right"></i>
        </button>

        <button class="btn btn-xs btn-ghost gap-1" @click="openCommentsModal">
          <i class="fa-solid fa-comment-dots"></i>
          <span class="badge badge-xs badge-info">{{ totalCommentCount }}</span>
        </button>

        <button class="btn btn-xs btn-ghost" @click="$emit('refresh')" :disabled="loading">
          <i class="fa-solid fa-rotate-right" :class="{ 'animate-spin': loading }"></i>
        </button>
      </div>
    </header>

    <div v-if="loading" class="flex items-center justify-center grow gap-2 text-base-content/50">
      <i class="fa-solid fa-spinner animate-spin text-xl"></i>
      <span>Loading changes...</span>
    </div>

    <template v-else-if="files?.length">
      <SplitterGroup class="grow" direction="horizontal">
        <!-- Left panel: File list -->
        <SplitterPanel :min-size="15" :defaultSize="25" :collapsible="true" class="overflow-hidden">
          <div class="flex flex-col h-full">
            <div class="flex items-center justify-between px-2 py-1.5 bg-base-200/50 border-b border-base-content/10 shrink-0">
              <span class="text-xs font-semibold">Files ({{ files.length }})</span>
              <div class="flex items-center gap-1">
                <button class="btn btn-xs btn-ghost" @click="selectAllFiles" title="Select all">
                  <i class="fa-solid fa-check-double text-[10px]"></i>
                </button>
                <button class="btn btn-xs btn-ghost" @click="clearSelection" title="Clear selection">
                  <i class="fa-solid fa-xmark text-[10px]"></i>
                </button>
              </div>
            </div>

            <div class="flex items-center gap-1 px-2 py-1.5 border-b border-base-content/10 shrink-0">
              <div class="relative grow">
                <i class="fa-solid fa-magnifying-glass absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-base-content/40"></i>
                <input
                  type="text"
                  v-model="fileFilter"
                  placeholder="Filter files..."
                  class="input input-xs input-bordered w-full pl-6"
                />
              </div>
            </div>

            <div class="grow overflow-y-auto">
              <template v-for="(folderFiles, folderPath) in visibleFilesByFolder" :key="folderPath">
                <div class="file-folder-group">
                  <div
                    class="flex items-center gap-1 px-2 py-1 text-xs font-semibold bg-base-200/80 cursor-pointer hover:bg-base-300/80"
                    @click="toggleFolder(folderPath)"
                  >
                    <i :class="folderExpanded[folderPath] ? 'fa-solid fa-chevron-down' : 'fa-solid fa-chevron-right'" class="text-[10px]"></i>
                    <i class="fa-solid fa-folder text-warning text-[10px]"></i>
                    <span class="truncate">{{ folderPath || '/' }}</span>
                    <span class="ml-auto text-[10px] text-base-content/40">{{ folderFiles.length }}</span>
                  </div>
                  <div v-if="folderExpanded[folderPath]" class="file-list pl-2 border-l border-base-content/10">
                    <div
                      v-for="file in folderFiles"
                      :key="file.fileFullName"
                      class="file-item flex items-center gap-1.5 px-2 py-1 text-xs cursor-pointer hover:bg-base-200"
                      :class="{ 'bg-base-200': selectedFile?.fileFullName === file.fileFullName }"
                      @click="selectFile(file)"
                    >
                      <input
                        type="checkbox"
                        v-model="file.selected"
                        class="checkbox checkbox-xs"
                        @click.stop
                        @change="onFileSelectionChange"
                      />
                      <i class="fa-solid fa-file text-[10px]" :class="getFileIconClass(file)"></i>
                      <span class="truncate grow">{{ file.title }}</span>
                      <!-- AI review score badge -->
                      <span
                        v-if="getFileAiSummary(file)"
                        class="badge badge-xs"
                        :class="getFileScoreBadgeClass(file)"
                        :title="`AI Score: ${getFileAiSummary(file).score}`"
                      >
                        {{ getFileAiSummary(file).score }}
                      </span>
                      <span class="badge badge-xs badge-success badge-ghost" v-if="file.insertions">+{{ file.insertions }}</span>
                      <span class="badge badge-xs badge-error badge-ghost" v-if="file.deletions">-{{ file.deletions }}</span>
                      <!-- AI open comment count -->
                      <span
                        v-if="getFileOpenAiCommentCount(file) > 0"
                        class="badge badge-xs badge-warning"
                        title="AI review comments"
                      >
                        <i class="fa-solid fa-robot text-[8px]"></i> {{ getFileOpenAiCommentCount(file) }}
                      </span>
                      <i class="fa-solid fa-comment-dots text-info text-[10px]" v-if="file.commentCount"></i>
                    </div>
                  </div>
                </div>
              </template>

              <div v-if="!visibleFiles.length" class="flex flex-col items-center justify-center py-8 text-base-content/40">
                <i class="fa-solid fa-filter text-2xl mb-2"></i>
                <span class="text-xs">No files match the filter</span>
              </div>
            </div>
          </div>
        </SplitterPanel>

        <SplitterResizeHandle class="w-1 hover:bg-slate-600" />

        <!-- Center panel: Diff viewer -->
        <SplitterPanel :min-size="30" :defaultSize="75" class="overflow-hidden">
          <div class="flex flex-col h-full">
            <!-- File tabs -->
            <div class="flex items-center gap-1 px-1 py-1 bg-base-200/30 border-b border-base-content/10 shrink-0 overflow-x-auto">
              <div
                v-for="file in recentlyViewedFiles"
                :key="file.fileFullName"
                class="file-tab flex items-center gap-1.5 px-2 py-1 text-xs rounded-md cursor-pointer whitespace-nowrap"
                :class="{
                  'bg-base-100 text-base-content': selectedFile?.fileFullName === file.fileFullName,
                  'hover:bg-base-200': selectedFile?.fileFullName !== file.fileFullName
                }"
                @click="selectFile(file)"
              >
                <i class="fa-solid fa-file text-[10px]" :class="getFileIconClass(file)"></i>
                <span class="truncate max-w-[150px]">{{ file.title }}</span>

                <!-- AI review button on tab -->
                <button
                  class="btn btn-xs btn-ghost h-4 px-1"
                  :class="{
                    'text-warning animate-pulse': reviewingFile === file.fileFullName,
                    'text-base-content/40 hover:text-warning': reviewingFile !== file.fileFullName
                  }"
                  @click.stop="$emit('review-file', file)"
                  :title="reviewingFile === file.fileFullName ? 'Reviewing...' : 'AI Review this file'"
                  :disabled="!!reviewingFile"
                >
                  <i class="fa-solid fa-robot text-[9px]"></i>
                </button>

                <button
                  class="btn btn-xs btn-ghost h-4 w-4 p-0"
                  @click.stop="closeFileTab(file)"
