                      {{ selectedFile.fileFullName }}
                    </span>
                    <span class="badge badge-xs" :class="getFileStatusBadge(selectedFile)">
                      {{ getFileStatusText(selectedFile) }}
                    </span>
                    <!-- AI review summary badge -->
