                      <span class="badge badge-xs badge-error" v-if="selectedFileAiErrorCount">
                        <i class="fa-solid fa-circle-xmark text-[8px]"></i> {{ selectedFileAiErrorCount }}
                      </span>
                      <span class="badge badge-xs badge-warning" v-if="selectedFileAiWarningCount">
