                      </span>
                      <span class="badge badge-xs badge-info" v-if="selectedFileAiSuggestionCount">
                        <i class="fa-solid fa-lightbulb text-[8px]"></i> {{ selectedFileAiSuggestionCount }}
                      </span>
                    </template>
                    <button
                      class="btn btn-xs gap-1"
                      :class="showFullFile ? 'btn-info btn-outline' : 'btn-ghost'"
                      @click="toggleFullFile"
