                      <div class="diff-line flex" :class="getFullFileLineClass(line)">
                        <div class="line-number w-12 shrink-0 text-right pr-2 select-none text-[11px] font-mono text-base-content/40">
                          {{ line.lineNumber }}
                        </div>
                        <div class="diff-indicator w-6 shrink-0 text-center select-none text-[11px] font-mono" :class="getDiffIndicatorClass(line)">
                          {{ getDiffIndicator(line) }}
                        </div>
                        <div class="line-content grow font-mono text-[11px] px-2 whitespace-pre">{{ line.content }}</div>
                      </div>
                    </template>
                  </template>

                  <template v-else>
                    <template v-for="(line, index) in selectedFile.diffLines" :key="index">
                      <div
                        class="diff-line flex"
                        :class="getLineClass(line, index)"
