                          {{ line.oldLineNumber }}
                        </div>
                        <div class="line-number w-12 shrink-0" v-else></div>

                        <div class="diff-indicator w-6 shrink-0 text-center select-none text-[11px] font-mono" :class="getDiffIndicatorClass(line)">
                          {{ getDiffIndicator(line) }}
                        </div>

                        <div
                          class="line-content grow font-mono text-[11px] px-2 whitespace-pre"
                          :class="{ 'cursor-pointer': !line.isContext, 'hover:bg-base-200/50': !line.isContext }"
                        >
                          {{ line.content }}
                        </div>

                        <div class="line-number w-12 shrink-0 text-right pr-2 select-none text-[11px] font-mono text-base-content/40"
                          v-if="line.newLineNumber !== null">
                          {{ line.newLineNumber }}
                        </div>
                        <div class="line-number w-12 shrink-0" v-else></div>

                        <!-- Comment actions: AI + user -->
                        <div class="comment-actions w-14 shrink-0 flex justify-center items-center gap-1">
                          <!-- AI comment badge -->
                          <template v-if="getLineAiComments(line).length">
                            <button
                              class="btn btn-xs btn-ghost h-5 px-1 text-warning"
                              @click.stop="toggleLineAiComments(line, index)"
                              :title="`${getLineAiComments(line).length} AI review comment(s)`"
                            >
                              <i class="fa-solid fa-robot text-[9px]"></i>
                              <span class="badge badge-xs badge-warning">{{ getLineAiComments(line).length }}</span>
                            </button>
                          </template>
                          <!-- User comment badge -->
                          <template v-if="getLineComments(line).length">
                            <button
                              class="btn btn-xs btn-ghost h-5 w-5 p-0 text-info"
                              @click.stop="toggleLineComments(line, index)"
                            >
                              <i class="fa-solid fa-comment text-[10px]"></i>
                              <span class="badge badge-xs badge-info">{{ getLineComments(line).length }}</span>
                            </button>
                          </template>
                          <template v-if="!getLineComments(line).length && !line.isContext">
                            <button
                              class="btn btn-xs btn-ghost h-5 w-5 p-0 text-base-content/30 hover:text-info"
                              @click.stop="startLineComment(line, index)"
                            >
                              <i class="fa-solid fa-plus text-[10px]"></i>
                            </button>
                          </template>
                        </div>
                      </div>

                      <!-- AI comments for this line -->
                      <div
