                        <div class="flex">
                          <div class="w-12 shrink-0"></div>
                          <div class="w-6 shrink-0"></div>
                          <div class="grow border-y border-warning/30 bg-warning/5 px-2 py-1.5">
                            <div
                              v-for="aiComment in getLineAiComments(line)"
                              :key="aiComment.id"
                              class="mb-1.5 last:mb-0"
                              :class="{ 'opacity-40': aiComment.status === 'false_positive' }"
                            >
                              <!-- Severity + category header -->
                              <div class="flex items-center gap-1.5 mb-0.5">
                                <i :class="getAiCommentSeverityIcon(aiComment)" class="text-[10px]"></i>
                                <span class="text-[9px] font-bold uppercase" :class="getAiCommentSeverityClass(aiComment)">
                                  {{ aiComment.severity }}
                                </span>
                                <span class="badge badge-xs badge-ghost text-[8px]">{{ aiComment.category }}</span>
                                <span class="text-[9px] font-semibold text-base-content/80 ml-1">{{ aiComment.title }}</span>
                                <!-- Status actions -->
                                <div class="ml-auto flex items-center gap-1">
                                  <button
                                    v-if="aiComment.status !== 'fixed'"
                                    class="btn btn-xs btn-ghost h-4 px-1 text-success text-[8px]"
                                    @click.stop="setAiCommentStatus(aiComment, 'fixed')"
                                    title="Mark as fixed"
                                  >
                                    <i class="fa-solid fa-check"></i> Fix
                                  </button>
                                  <button
                                    v-if="aiComment.status === 'fixed'"
                                    class="btn btn-xs btn-ghost h-4 px-1 text-base-content/40 text-[8px]"
                                    @click.stop="setAiCommentStatus(aiComment, 'open')"
                                    title="Reopen"
                                  >
                                    <i class="fa-solid fa-rotate-left"></i>
                                  </button>
                                  <button
                                    v-if="aiComment.status !== 'false_positive'"
                                    class="btn btn-xs btn-ghost h-4 px-1 text-base-content/40 text-[8px]"
                                    @click.stop="setAiCommentStatus(aiComment, 'false_positive')"
                                    title="False positive"
                                  >
                                    <i class="fa-solid fa-thumbs-down"></i>
                                  </button>
                                </div>
                              </div>
                              <!-- Message -->
                              <div class="text-[10px] text-base-content/80 ml-4" :class="{ 'line-through': aiComment.status === 'fixed' }">
                                {{ aiComment.message }}
                              </div>
                              <!-- Suggestion code -->
                              <div v-if="aiComment.suggestion" class="mt-0.5 ml-4 text-[9px] text-success/80 font-mono bg-base-200/50 px-1 rounded">
                                💡 {{ aiComment.suggestion }}
                              </div>
                            </div>
                          </div>
                          <div class="w-12 shrink-0"></div>
                          <div class="w-14 shrink-0"></div>
                        </div>
                      </div>

                      <!-- User inline comments -->
                      <div
                        v-if="isLineCommentsVisible(index) && getLineComments(line).length"
                        class="diff-line-comments flex"
