                        <div class="w-12 shrink-0"></div>
                        <div class="w-6 shrink-0"></div>
                        <div class="grow bg-info/10 border-y border-info/20 px-2 py-1">
                          <div class="flex items-center gap-1 mb-1">
                            <span class="text-[9px] text-info font-semibold">
                              <i class="fa-solid fa-comment-dots"></i>
                              {{ getLineComments(line).length }} comment{{ getLineComments(line).length > 1 ? 's' : '' }}
                            </span>
                            <button class="btn btn-xs btn-ghost h-4 w-4 p-0 ml-auto" @click.stop="hideLineComments(index)">
                              <i class="fa-solid fa-xmark text-[8px]"></i>
                            </button>
                          </div>
                          <div class="space-y-1">
                            <div
                              v-for="comment in getLineComments(line)"
                              :key="comment.id"
                              class="flex gap-1.5"
                              :class="{ 'opacity-60': comment.resolved }"
                            >
                              <div class="avatar shrink-0 mt-0.5">
                                <div class="w-4 h-4 rounded-full bg-base-300 flex items-center justify-center">
                                  <span class="text-[8px] font-semibold">{{ comment.author?.[0] || '?' }}</span>
                                </div>
                              </div>
                              <div class="grow min-w-0">
                                <div class="flex items-center justify-between gap-1">
                                  <div class="flex items-center gap-1">
                                    <span class="text-[9px] font-semibold">{{ comment.author || 'Anonymous' }}</span>
                                    <span class="text-[7px] text-base-content/40">{{ formatTime(comment.timestamp) }}</span>
                                  </div>
                                  <div class="flex items-center gap-0.5">
                                    <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px]" @click.stop="toggleResolve(comment)">
                                      <i :class="comment.resolved ? 'fa-solid fa-rotate-left' : 'fa-solid fa-check'"></i>
                                    </button>
                                    <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px] text-error" @click.stop="deleteComment(comment)">
                                      <i class="fa-solid fa-trash"></i>
                                    </button>
                                  </div>
                                </div>
                                <div class="text-[9px] mt-0.5 break-words" :class="{ 'line-through': comment.resolved }">
                                  {{ comment.content }}
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>
                        <div class="w-12 shrink-0"></div>
                        <div class="w-14 shrink-0"></div>
                      </div>

                      <!-- Comment input row -->
                      <div v-if="commentingLineIndex === index" class="diff-line-comment-input flex">
                        <div class="w-12 shrink-0"></div>
                        <div class="w-6 shrink-0"></div>
                        <div class="grow bg-base-200/50 border-y border-base-content/10 px-2 py-1.5">
                          <div class="flex items-start gap-2">
                            <div class="flex-1">
                              <div class="flex items-center gap-2 mb-1">
                                <span class="text-[10px] text-base-content/40 font-mono">
                                  Line {{ commentingLine?.newLineNumber || commentingLine?.oldLineNumber }}
                                </span>
                                <span class="text-[9px] text-base-content/30 truncate max-w-[200px]">
                                  {{ commentingLine?.content?.slice(0, 50) }}
                                </span>
                              </div>
                              <textarea
                                v-model="newComment"
                                placeholder="Add a comment..."
                                class="textarea textarea-xs textarea-bordered w-full min-h-[36px] resize-none"
                                @keydown.enter.exact.prevent="submitComment"
                                ref="commentInput"
                              ></textarea>
                            </div>
                            <div class="flex flex-col gap-1 shrink-0">
                              <button class="btn btn-xs btn-primary" @click="submitComment" :disabled="!newComment.trim()">
                                <i class="fa-solid fa-paper-plane text-[10px]"></i>
                              </button>
                              <button class="btn btn-xs btn-ghost" @click="cancelComment">
                                <i class="fa-solid fa-xmark text-[10px]"></i>
                              </button>
                            </div>
                          </div>
                        </div>
                        <div class="w-12 shrink-0"></div>
                        <div class="w-14 shrink-0"></div>
                      </div>
                    </template>
                  </template>
                </div>

                <!-- SPLIT VIEW (unchanged layout, omitting for brevity - same structure) -->
                <div v-else class="diff-lines-split flex">
                  <div class="diff-side w-1/2 border-r border-base-content/10 overflow-auto">
                    <div class="px-2 py-1 bg-base-200/80 text-[10px] font-semibold flex items-center gap-1">
                      <i class="fa-solid fa-file text-error"></i>
                      <span>{{ selectedFile.oldFile.fileName || 'original' }}</span>
                    </div>
                    <div class="diff-side-lines">
                      <template v-for="(line, index) in selectedFile.splitLines.old" :key="'old-' + index">
                        <div
                          class="diff-line flex"
                          :class="getSplitLineClass(line, index, 'old')"
                          @click="onSplitLineClick(line, index, 'old')"
                        >
                          <div class="line-number w-12 shrink-0 text-right pr-2 select-none text-[11px] font-mono text-base-content/40">
                            {{ line.oldLineNumber }}
                          </div>
                          <div class="diff-indicator w-6 shrink-0 text-center select-none text-[11px] font-mono text-error">
                            {{ getSplitDiffIndicator(line) }}
                          </div>
                          <div class="line-content grow font-mono text-[11px] px-2 whitespace-pre">{{ line.content }}</div>
                          <div class="comment-actions w-8 shrink-0 flex justify-center items-center gap-1">
                            <template v-if="getSplitLineComments(line, 'old').length">
                              <button class="btn btn-xs btn-ghost h-5 w-5 p-0 text-info" @click.stop="toggleSplitLineComments(line, index, 'old')">
                                <i class="fa-solid fa-comment text-[10px]"></i>
                                <span class="badge badge-xs badge-info">{{ getSplitLineComments(line, 'old').length }}</span>
                              </button>
                            </template>
                            <template v-else-if="line.type === 'del'">
                              <button class="btn btn-xs btn-ghost h-5 w-5 p-0 text-base-content/30 hover:text-info" @click.stop="startSplitLineComment(line, index, 'old')">
                                <i class="fa-solid fa-plus text-[10px]"></i>
                              </button>
                            </template>
                          </div>
                        </div>
                        <div v-if="isSplitLineCommentsVisible(index, 'old') && getSplitLineComments(line, 'old').length" class="diff-line-comments flex">
                          <div class="w-12 shrink-0"></div>
                          <div class="w-6 shrink-0"></div>
                          <div class="grow bg-info/10 border-y border-info/20 px-2 py-1">
                            <div class="space-y-1">
                              <div v-for="comment in getSplitLineComments(line, 'old')" :key="comment.id" class="flex gap-1.5" :class="{ 'opacity-60': comment.resolved }">
                                <div class="grow min-w-0">
                                  <div class="flex items-center justify-between gap-1">
                                    <span class="text-[9px] font-semibold">{{ comment.author || 'Anonymous' }}</span>
                                    <div class="flex items-center gap-0.5">
                                      <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px]" @click.stop="toggleResolve(comment)">
                                        <i :class="comment.resolved ? 'fa-solid fa-rotate-left' : 'fa-solid fa-check'"></i>
                                      </button>
                                      <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px] text-error" @click.stop="deleteComment(comment)">
                                        <i class="fa-solid fa-trash"></i>
                                      </button>
                                    </div>
                                  </div>
                                  <div class="text-[9px] mt-0.5 break-words" :class="{ 'line-through': comment.resolved }">{{ comment.content }}</div>
                                </div>
                              </div>
                            </div>
                          </div>
                          <div class="w-8 shrink-0"></div>
                        </div>
                      </template>
                    </div>
                  </div>

                  <div class="diff-side w-1/2 overflow-auto">
                    <div class="px-2 py-1 bg-base-200/80 text-[10px] font-semibold flex items-center gap-1">
                      <i class="fa-solid fa-file text-success"></i>
                      <span>{{ selectedFile.newFile.fileName || 'modified' }}</span>
                    </div>
                    <div class="diff-side-lines">
                      <template v-for="(line, index) in selectedFile.splitLines.new" :key="'new-' + index">
                        <div
                          class="diff-line flex"
                          :class="getSplitLineClass(line, index, 'new')"
                          @click="onSplitLineClick(line, index, 'new')"
                        >
                          <div class="line-number w-12 shrink-0 text-right pr-2 select-none text-[11px] font-mono text-base-content/40">
                            {{ line.newLineNumber }}
                          </div>
                          <div class="diff-indicator w-6 shrink-0 text-center select-none text-[11px] font-mono text-success">
                            {{ getSplitDiffIndicator(line) }}
                          </div>
                          <div class="line-content grow font-mono text-[11px] px-2 whitespace-pre">{{ line.content }}</div>
                          <div class="comment-actions w-8 shrink-0 flex justify-center items-center gap-1">
                            <template v-if="getSplitLineComments(line, 'new').length">
                              <button class="btn btn-xs btn-ghost h-5 w-5 p-0 text-info" @click.stop="toggleSplitLineComments(line, index, 'new')">
                                <i class="fa-solid fa-comment text-[10px]"></i>
                                <span class="badge badge-xs badge-info">{{ getSplitLineComments(line, 'new').length }}</span>
                              </button>
                            </template>
                            <template v-else-if="line.type === 'add'">
                              <button class="btn btn-xs btn-ghost h-5 w-5 p-0 text-base-content/30 hover:text-info" @click.stop="startSplitLineComment(line, index, 'new')">
                                <i class="fa-solid fa-plus text-[10px]"></i>
                              </button>
                            </template>
                          </div>
                        </div>
                        <div v-if="isSplitLineCommentsVisible(index, 'new') && getSplitLineComments(line, 'new').length" class="diff-line-comments flex">
                          <div class="w-12 shrink-0"></div>
                          <div class="w-6 shrink-0"></div>
                          <div class="grow bg-info/10 border-y border-info/20 px-2 py-1">
                            <div class="space-y-1">
                              <div v-for="comment in getSplitLineComments(line, 'new')" :key="comment.id" class="flex gap-1.5" :class="{ 'opacity-60': comment.resolved }">
                                <div class="grow min-w-0">
                                  <div class="flex items-center justify-between gap-1">
                                    <span class="text-[9px] font-semibold">{{ comment.author || 'Anonymous' }}</span>
                                    <div class="flex items-center gap-0.5">
                                      <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px]" @click.stop="toggleResolve(comment)">
                                        <i :class="comment.resolved ? 'fa-solid fa-rotate-left' : 'fa-solid fa-check'"></i>
                                      </button>
                                      <button class="btn btn-xs btn-ghost h-auto py-0 px-0.5 text-[7px] text-error" @click.stop="deleteComment(comment)">
                                        <i class="fa-solid fa-trash"></i>
                                      </button>
                                    </div>
                                  </div>
                                  <div class="text-[9px] mt-0.5 break-words" :class="{ 'line-through': comment.resolved }">{{ comment.content }}</div>
                                </div>
                              </div>
                            </div>
                          </div>
                          <div class="w-8 shrink-0"></div>
                        </div>
                      </template>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </SplitterPanel>
      </SplitterGroup>
    </template>

    <div v-else class="flex flex-col items-center justify-center grow text-base-content/40">
      <i class="fa-solid fa-inbox text-4xl mb-3"></i>
      <span class="text-sm">No changes found between branches</span>
    </div>

    <!-- Comments Modal -->
    <dialog id="commentsModal" class="modal" ref="commentsModal">
      <div class="modal-box w-11/12 max-w-3xl">
        <div class="flex items-center justify-between mb-4">
          <div class="flex items-center gap-2">
            <i class="fa-solid fa-comment-dots text-info"></i>
            <h3 class="font-bold">Comments</h3>
            <span class="badge badge-info">{{ totalCommentCount }}</span>
          </div>
          <button class="btn btn-xs btn-ghost" @click="closeCommentsModal">
            <i class="fa-solid fa-xmark"></i>
          </button>
        </div>

        <div class="tabs tabs-boxed tabs-xs mb-4">
          <a class="tab" :class="{ 'tab-active': commentFilter === 'all' }" @click="commentFilter = 'all'">All</a>
          <a class="tab" :class="{ 'tab-active': commentFilter === 'unresolved' }" @click="commentFilter = 'unresolved'">Unresolved</a>
          <a class="tab" :class="{ 'tab-active': commentFilter === 'resolved' }" @click="commentFilter = 'resolved'">Resolved</a>
        </div>

        <div class="overflow-y-auto max-h-[60vh] space-y-2">
          <div v-if="!filteredAllComments.length" class="flex flex-col items-center justify-center py-8 text-base-content/40">
            <i class="fa-regular fa-comment-slash text-2xl mb-2"></i>
            <span class="text-xs">No comments</span>
          </div>
          <div
            v-for="comment in filteredAllComments"
            :key="comment.id"
            class="flex gap-2 p-2 rounded bg-base-200/30"
            :class="{ 'opacity-50': comment.resolved }"
          >
            <div class="avatar shrink-0 mt-0.5">
              <div class="w-6 h-6 rounded-full bg-base-300 flex items-center justify-center">
                <span class="text-[10px] font-semibold">{{ comment.author?.[0] || '?' }}</span>
              </div>
            </div>
            <div class="grow min-w-0">
              <div class="flex items-center justify-between gap-2">
                <div class="flex items-center gap-2">
                  <span class="text-xs font-semibold">{{ comment.author || 'Anonymous' }}</span>
                  <span class="text-[10px] text-base-content/40">{{ formatTime(comment.timestamp) }}</span>
                </div>
                <div class="flex items-center gap-1">
                  <button class="btn btn-xs btn-ghost h-auto py-0 px-1 text-[9px]" @click="toggleResolve(comment)">
                    <i :class="comment.resolved ? 'fa-solid fa-rotate-left' : 'fa-solid fa-check'"></i>
                  </button>
                  <button class="btn btn-xs btn-ghost h-auto py-0 px-1 text-[9px] text-error" @click="deleteComment(comment)">
                    <i class="fa-solid fa-trash"></i>
                  </button>
                </div>
              </div>
              <div class="flex items-center gap-2 mt-1 text-[10px] text-base-content/40">
                <span class="font-mono truncate">{{ comment.fileName }}</span>
                <span>Line {{ comment.lineNumber }}</span>
                <span class="badge badge-xs" :class="comment.lineType === 'old' ? 'badge-error' : 'badge-success'">
                  {{ comment.lineType === 'old' ? 'Original' : 'New' }}
                </span>
              </div>
              <div class="text-xs mt-1 break-words" :class="{ 'line-through': comment.resolved }">{{ comment.content }}</div>
              <button class="btn btn-xs btn-ghost h-auto py-0 px-1 mt-1 text-[9px] text-info" @click="jumpToComment(comment)">
                <i class="fa-solid fa-arrow-up-right-from-square"></i> Jump to line
              </button>
            </div>
          </div>
        </div>
      </div>
      <form method="dialog" class="modal-backdrop"><button>close</button></form>
    </dialog>
  </div>
</template>

<script>
const parser = new DiffParser()

export default {
  props: {
    fromBranch: { type: String, default: 'main' },
    toBranch: { type: String, default: 'develop' },
    availableBranches: { type: Array, default: () => [] },
    repoChanges: { type: Object, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    // AI comments from PRChangesPanel, keyed by file_path
    aiCommentsByFile: { type: Object, default: () => ({}) },
    // File path currently being reviewed (for loading indicator)
    reviewingFile: { type: String, default: null }
  },
  emits: ['refresh', 'comment', 'select-branch', 'chat-message', 'branch-changed', 'compare-branch-changed',
          'visible-files-changed', 'selected-files-changed', 'review-file', 'ai-comment-status-changed'],
  data() {
    return {
      files: null,
      selectedFile: null,
      recentlyViewedFiles: [],
      fileFilter: '',
      diffViewMode: 'unified',
      newComment: '',
      commentingLine: null,
      commentingLineIndex: null,
      commentsByFile: {},
      folderExpanded: {},
      commentFilter: 'all',
      commentsModalOpen: false,
      visibleLineComments: new Set(),
      splitCommentingLine: null,
      splitCommentingIndex: null,
      splitCommentingSide: null,
      splitVisibleLineCommentsOld: new Set(),
      splitVisibleLineCommentsNew: new Set(),
      showFullFile: false,
      fullFileLines: [],
      fullFileLoading: false,
      // Tracks which line indexes have AI comment panels open
      visibleAiLineComments: new Set()
    }
  },
  created() {
    if (this.repoChanges) this.buildFiles()
  },
  computed: {
    visibleFiles() {
      if (!this.files) return []
      if (!this.fileFilter) return this.files
      const filter = this.fileFilter.toLowerCase()
      return this.files.filter(f =>
        f.fileFullName.toLowerCase().includes(filter) ||
        f.title.toLowerCase().includes(filter)
      )
    },

    visibleFilesByFolder() {
      if (!this.visibleFiles.length) return {}
      const grouped = {}
      this.visibleFiles.forEach(file => {
        const lastSlashIndex = file.fileFullName.lastIndexOf('/')
        const folderPath = lastSlashIndex > 0 ? file.fileFullName.substring(0, lastSlashIndex) : '/'
        if (!grouped[folderPath]) grouped[folderPath] = []
        grouped[folderPath].push(file)
      })
      const sorted = {}
      Object.keys(grouped).sort().forEach(key => { sorted[key] = grouped[key] })
      return sorted
    },

    changeCount() { return this.files?.length || 0 },
    insertions() { return this.files?.reduce((sum, f) => sum + (f.insertions || 0), 0) || 0 },
    deletions() { return this.files?.reduce((sum, f) => sum + (f.deletions || 0), 0) || 0 },

    selectedFileIndex() {
      if (!this.selectedFile || !this.visibleFiles.length) return -1
      return this.visibleFiles.findIndex(f => f.fileFullName === this.selectedFile.fileFullName)
    },
    hasPreviousFile() { return this.selectedFileIndex > 0 },
    hasNextFile() { return this.selectedFileIndex < this.visibleFiles.length - 1 },

    fileComments() {
      if (!this.selectedFile) return []
      return this.commentsByFile[this.selectedFile.fileFullName] || []
    },
    totalCommentCount() {
      return Object.values(this.commentsByFile).reduce((sum, comments) => sum + comments.length, 0)
    },
    allComments() {
      const comments = []
      Object.entries(this.commentsByFile).forEach(([fileName, fileComments]) => {
        fileComments.forEach(comment => comments.push({ ...comment, fileName }))
      })
      return comments.sort((a, b) => b.timestamp - a.timestamp)
    },
    filteredAllComments() {
      if (this.commentFilter === 'all') return this.allComments
      if (this.commentFilter === 'unresolved') return this.allComments.filter(c => !c.resolved)
      return this.allComments.filter(c => c.resolved)
    },

    /** AI comments for the currently selected file */
    selectedFileAiComments() {
      if (!this.selectedFile) return []
      return (this.aiCommentsByFile[this.selectedFile.fileFullName] || [])
        .filter(c => c.status !== 'false_positive')
    },

    selectedFileAiSummary() {
      if (!this.selectedFile) return null
      const prView = this.chat?.metadata?.pr_view?.[this.selectedFile.fileFullName]
      if (!prView?.score && !prView?.summary) return null
      return { score: prView.score, summary: prView.summary }
    },

    selectedFileAiErrorCount() {
      return this.selectedFileAiComments.filter(c => c.severity === 'error' && c.status === 'open').length
    },
    selectedFileAiWarningCount() {
      return this.selectedFileAiComments.filter(c => c.severity === 'warning' && c.status === 'open').length
    },
    selectedFileAiSuggestionCount() {
      return this.selectedFileAiComments.filter(c => c.severity === 'suggestion' && c.status === 'open').length
    }
  },
  watch: {
    repoChanges(newChanges) {
      if (newChanges) this.buildFiles()
      else { this.files = null; this.selectedFile = null }
    },
    fileFilter() {
      if (!this.visibleFiles.find(f => f.fileFullName === this.selectedFile?.fileFullName)) {
        this.selectedFile = null
      }
      this.$emit('visible-files-changed', this.visibleFiles)
    },
    selectedFile() {
      this.visibleLineComments.clear()
      this.splitVisibleLineCommentsOld.clear()
      this.splitVisibleLineCommentsNew.clear()
      this.visibleAiLineComments.clear()
      this.fullFileLines = []
      if (this.showFullFile) this.loadFullFile()
      this.$nextTick(() => this.autoExpandCommentedLines())
    },
    diffViewMode() {
      this.commentingLine = null
      this.commentingLineIndex = null
      this.splitCommentingLine = null
      this.splitCommentingIndex = null
      this.splitCommentingSide = null
      this.newComment = ''
      this.$nextTick(() => this.autoExpandCommentedLines())
    },
    showFullFile(val) {
      if (val && this.selectedFile) this.loadFullFile()
      else this.fullFileLines = []
    }
  },
  methods: {
    setDiffViewMode(mode) { this.diffViewMode = mode },

    async toggleFullFile() { this.showFullFile = !this.showFullFile },

    async loadFullFile() {
      if (!this.selectedFile || !this.project?.$api) return
      this.fullFileLoading = true
      try {
        const content = await this.project.$api.files.read(this.selectedFile.fileFullName)
        const rawLines = (content?.page_content || content || '').split('\n')
        this.fullFileLines = rawLines.map((text, idx) => {
          const lineNumber = idx + 1
          const diffLine = this.selectedFile.diffLines?.find(
            l => l.newLineNumber === lineNumber || l.oldLineNumber === lineNumber
          )
          return { lineNumber, content: text, type: diffLine?.type || 'context', isContext: !diffLine || diffLine.isContext }
        })
      } catch (err) {
        console.error('Error loading full file:', err)
        this.fullFileLines = []
        this.showFullFile = false
      } finally {
        this.fullFileLoading = false
      }
    },

    getFullFileLineClass(line) {
      if (line.type === 'add') return 'bg-success/10'
      if (line.type === 'del') return 'bg-error/10'
      return ''
    },

    onFromBranchChanged(branch) { this.$emit('branch-changed', branch) },
    onToBranchChanged(branch) { this.$emit('compare-branch-changed', branch) },

    /** Emit selected files list whenever selection changes */
    onFileSelectionChange() {
      this.$emit('selected-files-changed', this.visibleFiles.filter(f => f.selected))
    },

    buildFiles() {
      if (!this.repoChanges?.branch_file_and_commits) { this.files = null; return }
      const { branch_file_and_commits } = this.repoChanges
      const repoPath = this.repoChanges.repo_path || ''
      this.files = Object.keys(branch_file_and_commits)
        .map(filePath => this.buildDiffFile(branch_file_and_commits[filePath].diff, repoPath))
        .filter(Boolean)
        .sort((a, b) => a.fileFullName.localeCompare(b.fileFullName))

      Object.keys(this.visibleFilesByFolder).forEach(folder => {
        if (this.folderExpanded[folder] === undefined) this.folderExpanded[folder] = true
      })

      if (this.files.length && !this.selectedFile) this.selectFile(this.files[0])
      this.$emit('visible-files-changed', this.visibleFiles)
    },

    buildDiffFile(diff, repoPath) {
      try {
        const lines = diff.replace('diff --git ', '').split('\n')
        const [oldFile, newFile] = lines[0].trim().split(' ')
        const oldName = oldFile?.replace('a/', '') || ''
        const newName = newFile?.replace('b/', '') || ''
        const isDeleted = diff.includes('deleted file mode') || false
        const isNewFile = !isDeleted && newName && !oldName
        const fileName = oldName || newName
        const fileFullName = fileName.startsWith(repoPath)
          ? fileName
          : repoPath + (fileName[0] === '/' ? '' : '/') + fileName
        const title = fileName.split('/').pop()
        const diffLines = this.parseDiffLines(diff)
        const splitLines = this.parseSplitLines(diff)
        let insertions = 0, deletions = 0
        diffLines.forEach(line => {
          if (line.type === 'add') insertions++
          if (line.type === 'del') deletions++
        })
        return {
          title, fileName, fileFullName, diff, diffLines, splitLines,
          oldFile: { fileName: oldName }, newFile: { fileName: newName },
          isDeleted, isNewFile, isChanged: !isDeleted && newName && oldName,
          insertions, deletions, selected: false, commentCount: 0
        }
      } catch (ex) {
        console.error('Error parsing diff:', ex)
        return null
      }
    },

    parseDiffLines(diff) {
      const lines = diff.split('\n')
      const result = []
      let oldLineNum = 0, newLineNum = 0
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (line.startsWith('diff --git') || line.startsWith('index ') || line.startsWith('--- ') || line.startsWith('+++ ')) continue
        if (line.startsWith('@@')) {
          const match = line.match(/@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/)
          if (match) { oldLineNum = parseInt(match[1]); newLineNum = parseInt(match[2]) }
          result.push({ type: 'hunk', content: line, oldLineNumber: null, newLineNumber: null, isContext: false })
          continue
        }
        if (line.startsWith('+') && !line.startsWith('+++')) {
          result.push({ type: 'add', content: line, oldLineNumber: null, newLineNumber: newLineNum++, isContext: false })
        } else if (line.startsWith('-') && !line.startsWith('---')) {
          result.push({ type: 'del', content: line, oldLineNumber: oldLineNum++, newLineNumber: null, isContext: false })
        } else {
          result.push({ type: 'context', content: line, oldLineNumber: oldLineNum++, newLineNumber: newLineNum++, isContext: true })
        }
      }
      return result
    },

    parseSplitLines(diff) {
      const lines = diff.split('\n')
      const oldLines = [], newLines = []
      let oldLineNum = 0, newLineNum = 0
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (line.startsWith('diff --git') || line.startsWith('index ') || line.startsWith('--- ') || line.startsWith('+++ ')) continue
        if (line.startsWith('@@')) {
          const match = line.match(/@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/)
          if (match) { oldLineNum = parseInt(match[1]); newLineNum = parseInt(match[2]) }
          oldLines.push({ type: 'hunk', content: line, oldLineNumber: null })
          newLines.push({ type: 'hunk', content: line, newLineNumber: null })
          continue
        }
        if (line.startsWith('+') && !line.startsWith('+++')) {
          newLines.push({ type: 'add', content: line, newLineNumber: newLineNum++ })
        } else if (line.startsWith('-') && !line.startsWith('---')) {
          oldLines.push({ type: 'del', content: line, oldLineNumber: oldLineNum++ })
        } else {
          oldLines.push({ type: 'context', content: line, oldLineNumber: oldLineNum++ })
          newLines.push({ type: 'context', content: line, newLineNumber: newLineNum++ })
        }
      }
      return { old: oldLines, new: newLines }
    },

    selectFile(file) {
      this.selectedFile = file
      this.commentingLine = null
      this.commentingLineIndex = null
      this.splitCommentingLine = null
      this.splitCommentingIndex = null
      this.splitCommentingSide = null
      this.newComment = ''
      if (!this.recentlyViewedFiles.find(f => f.fileFullName === file.fileFullName)) {
        this.recentlyViewedFiles.unshift(file)
        if (this.recentlyViewedFiles.length > 10) this.recentlyViewedFiles = this.recentlyViewedFiles.slice(0, 10)
      }
    },

    closeFileTab(file) {
      this.recentlyViewedFiles = this.recentlyViewedFiles.filter(f => f.fileFullName !== file.fileFullName)
      if (this.selectedFile?.fileFullName === file.fileFullName) {
        this.selectedFile = this.recentlyViewedFiles[0] || null
      }
    },

    navigateFile(direction) {
      if (!this.visibleFiles.length) return
      const newIndex = this.selectedFileIndex + direction
      if (newIndex >= 0 && newIndex < this.visibleFiles.length) this.selectFile(this.visibleFiles[newIndex])
    },

    toggleFolder(folderPath) { this.folderExpanded[folderPath] = !this.folderExpanded[folderPath] },

    selectAllFiles() {
      this.visibleFiles.forEach(f => { f.selected = true })
      this.$emit('selected-files-changed', this.visibleFiles.filter(f => f.selected))
    },
    clearSelection() {
      this.visibleFiles.forEach(f => { f.selected = false })
      this.$emit('selected-files-changed', [])
    },

    autoExpandCommentedLines() {
      if (!this.selectedFile) return
      const fileComments = this.commentsByFile[this.selectedFile.fileFullName] || []
      fileComments.forEach(comment => {
        const lineIndex = this.selectedFile.diffLines.findIndex(l => {
          const matchOld = comment.lineType === 'old' && l.oldLineNumber === comment.lineNumber
          const matchNew = comment.lineType === 'new' && l.newLineNumber === comment.lineNumber
          return matchOld || matchNew
        })
        if (lineIndex !== -1) this.visibleLineComments.add(lineIndex)
      })
    },

    onLineClick(line, index) {
      if (line.isContext) return
      this.commentingLine = null
      this.commentingLineIndex = null
    },

    startLineComment(line, index) {
      this.commentingLine = line
      this.commentingLineIndex = index
      this.newComment = ''
      this.$nextTick(() => { const input = this.$refs.commentInput; if (input) input.focus() })
    },

    toggleLineComments(line, index) {
      if (this.visibleLineComments.has(index)) this.visibleLineComments.delete(index)
      else this.visibleLineComments.add(index)
    },
    isLineCommentsVisible(index) { return this.visibleLineComments.has(index) },
    hideLineComments(index) { this.visibleLineComments.delete(index) },

    /** Toggle AI comment panel for a given line index */
    toggleLineAiComments(line, index) {
      if (this.visibleAiLineComments.has(index)) this.visibleAiLineComments.delete(index)
      else this.visibleAiLineComments.add(index)
    },
    isLineAiCommentsVisible(index) { return this.visibleAiLineComments.has(index) },

    cancelComment() {
      this.commentingLine = null
      this.commentingLineIndex = null
      this.splitCommentingLine = null
      this.splitCommentingIndex = null
      this.splitCommentingSide = null
      this.newComment = ''
    },

    submitComment() {
      if (!this.newComment.trim() || !this.selectedFile) return
      let line, lineNumber, lineType
      if (this.diffViewMode === 'unified') {
        line = this.commentingLine
        if (!line) return
        lineNumber = line.newLineNumber || line.oldLineNumber
        lineType = line.newLineNumber ? 'new' : 'old'
      } else {
        line = this.splitCommentingLine
        if (!line) return
        lineType = this.splitCommentingSide
        lineNumber = lineType === 'old' ? line.oldLineNumber : line.newLineNumber
      }
      const comment = {
        id: Date.now().toString(),
        content: this.newComment.trim(),
        author: 'User',
        timestamp: Date.now(),
        resolved: false,
        lineNumber, lineType, lineContent: line.content, replies: []
      }
      if (!this.commentsByFile[this.selectedFile.fileFullName]) {
        this.commentsByFile[this.selectedFile.fileFullName] = []
      }
      this.commentsByFile[this.selectedFile.fileFullName].push(comment)
      this.selectedFile.commentCount = (this.selectedFile.commentCount || 0) + 1
      this.$emit('comment', { file: this.selectedFile, line, comment: comment.content, lineNumber, lineType: comment.lineType })
      this.autoExpandCommentedLines()
      this.cancelComment()
    },

    toggleResolve(comment) { comment.resolved = !comment.resolved },

    deleteComment(comment) {
      if (!this.selectedFile) return
      const comments = this.commentsByFile[this.selectedFile.fileFullName]
      const index = comments.indexOf(comment)
      if (index > -1) {
        comments.splice(index, 1)
        this.selectedFile.commentCount = Math.max(0, (this.selectedFile.commentCount || 0) - 1)
      }
    },

    getLineComments(line) {
      if (!this.selectedFile) return []
      return this.fileComments.filter(c => {
        if (c.lineType === 'old' && line.oldLineNumber === c.lineNumber) return true
        if (c.lineType === 'new' && line.newLineNumber === c.lineNumber) return true
        return false
      })
    },

    /** Get AI comments for a diff line, matching by new or old line number */
    getLineAiComments(line) {
      if (!this.selectedFile) return []
      const aiComments = this.aiCommentsByFile[this.selectedFile.fileFullName] || []
      return aiComments.filter(c => {
        if (c.status === 'false_positive') return false
        // AI comments reference line number (prefer new lines for added, old for deleted)
        if (line.type === 'add' && line.newLineNumber === c.line) return true
        if (line.type === 'del' && line.oldLineNumber === c.line) return true
        return false
      })
    },

    /** Emit status change for an AI comment up to PRChangesPanel for persistence */
    setAiCommentStatus(aiComment, status) {
      if (!this.selectedFile) return
      aiComment.status = status
      // Auto-open comments panel if marking as fixed
      this.$emit('ai-comment-status-changed', {
        filePath: this.selectedFile.fileFullName,
        commentId: aiComment.id,
        status
      })
    },

    /** Get AI comment count (open only) for file list display */
    getFileOpenAiCommentCount(file) {
      const comments = this.aiCommentsByFile[file.fileFullName] || []
      return comments.filter(c => c.status === 'open').length
    },

    getFileAiSummary(file) {
      const prView = this.chat?.metadata?.pr_view?.[file.fileFullName]
      if (!prView?.score) return null
      return { score: prView.score, summary: prView.summary }
    },

    /** Color badge based on AI score */
    getFileScoreBadgeClass(file) {
      const summary = this.getFileAiSummary(file)
      if (!summary) return 'badge-ghost'
      if (summary.score >= 80) return 'badge-success'
      if (summary.score >= 60) return 'badge-warning'
      return 'badge-error'
    },

    getLineClass(line, index) {
      const classes = []
      if (line.type === 'add') classes.push('bg-success/10')
      if (line.type === 'del') classes.push('bg-error/10')
      if (this.commentingLineIndex === index) classes.push('bg-info/20')
      if (this.getLineComments(line).length) classes.push('border-l-2 border-info')
      // Highlight lines with AI comments
      if (this.getLineAiComments(line).length) classes.push('border-l-2 border-warning')
      return classes.join(' ')
    },

    getDiffIndicatorClass(line) {
      if (line.type === 'add') return 'text-success'
      if (line.type === 'del') return 'text-error'
      return 'text-base-content/20'
    },

    getDiffIndicator(line) {
      if (line.type === 'add') return '+'
      if (line.type === 'del') return '-'
      if (line.type === 'hunk') return '~'
      return ' '
    },

    getSplitLineClass(line, index, side) {
      const classes = []
      if (line.type === 'add') classes.push('bg-success/10')
      if (line.type === 'del') classes.push('bg-error/10')
      if (this.splitCommentingSide === side && this.splitCommentingIndex === index) classes.push('bg-info/20')
      if (this.getSplitLineComments(line, side).length) classes.push('border-l-2 border-info')
      return classes.join(' ')
    },

    getSplitDiffIndicator(line) {
      if (line.type === 'add') return '+'
      if (line.type === 'del') return '-'
      if (line.type === 'hunk') return '~'
      return ' '
    },

    onSplitLineClick(line, index, side) {
      if (line.type === 'context') return
      this.splitCommentingLine = null
      this.splitCommentingIndex = null
      this.splitCommentingSide = null
    },

    startSplitLineComment(line, index, side) {
      this.splitCommentingLine = line
      this.splitCommentingIndex = index
      this.splitCommentingSide = side
      this.newComment = ''
      this.$nextTick(() => { const input = this.$refs.commentInput; if (input) input.focus() })
    },

    toggleSplitLineComments(line, index, side) {
      const set = side === 'old' ? this.splitVisibleLineCommentsOld : this.splitVisibleLineCommentsNew
      if (set.has(index)) set.delete(index); else set.add(index)
    },

    isSplitLineCommentsVisible(index, side) {
      return (side === 'old' ? this.splitVisibleLineCommentsOld : this.splitVisibleLineCommentsNew).has(index)
    },

    hideSplitLineComments(index, side) {
      (side === 'old' ? this.splitVisibleLineCommentsOld : this.splitVisibleLineCommentsNew).delete(index)
    },

    getSplitLineComments(line, side) {
      if (!this.selectedFile) return []
      return this.fileComments.filter(c => {
        if (c.lineType !== side) return false
        if (side === 'old') return line.oldLineNumber === c.lineNumber
        return line.newLineNumber === c.lineNumber
      })
    },

    /** Severity icon for AI comment */
    getAiCommentSeverityIcon(comment) {
      const map = {
        error: 'fa-solid fa-circle-xmark text-error',
        warning: 'fa-solid fa-triangle-exclamation text-warning',
        info: 'fa-solid fa-circle-info text-info',
        suggestion: 'fa-solid fa-lightbulb text-success'
      }
      return map[comment.severity] || 'fa-solid fa-circle-info text-info'
    },

    /** Severity text color class */
    getAiCommentSeverityClass(comment) {
      const map = {
        error: 'text-error',
        warning: 'text-warning',
        info: 'text-info',
        suggestion: 'text-success'
      }
      return map[comment.severity] || 'text-info'
    },

    getFileIconClass(file) {
      if (file.isNewFile) return 'text-success'
      if (file.isDeleted) return 'text-error'
      return 'text-warning'
    },

    getFileStatusBadge(file) {
      if (file.isNewFile) return 'badge-success'
      if (file.isDeleted) return 'badge-error'
      return 'badge-warning'
    },

    getFileStatusText(file) {
      if (file.isNewFile) return 'Added'
      if (file.isDeleted) return 'Deleted'
      return 'Modified'
    },

    copyDiff() {
      if (!this.selectedFile) return
      navigator.clipboard.writeText(['```diff', this.selectedFile.diff, '```'].join('\n'))
    },

    openInEditor() {
      if (!this.selectedFile) return
      this.$emit('open-file', this.selectedFile.fileFullName)
    },

    formatTime(timestamp) {
      const diff = Date.now() - timestamp
      if (diff < 60000) return 'just now'
      if (diff < 3600000) return Math.floor(diff / 60000) + 'm ago'
      if (diff < 86400000) return Math.floor(diff / 3600000) + 'h ago'
      return new Date(timestamp).toLocaleDateString()
    },

    openCommentsModal() { this.$refs.commentsModal.showModal() },
    closeCommentsModal() { this.$refs.commentsModal.close() },

    jumpToComment(comment) {
      const file = this.files.find(f => f.fileFullName === comment.fileName)
      if (file) {
        this.selectFile(file)
        const lineIndex = file.diffLines.findIndex(l => {
          const matchOld = comment.lineType === 'old' && l.oldLineNumber === comment.lineNumber
          const matchNew = comment.lineType === 'new' && l.newLineNumber === comment.lineNumber
          return matchOld || matchNew
        })
        if (lineIndex !== -1) this.visibleLineComments.add(lineIndex)
      }
      this.closeCommentsModal()
    }
  },
  expose: ['buildFiles', 'files', 'visibleFiles', 'selectFile', 'visibleLineComments']
}
</script>
```

